spec.expr:
min by (region) (
  sum by (region, node) (
    up{service_name=~"appliance-.*-(host|caddy)", appliance=~"$stage-.*", region=~"($region)"}
  )
)

max by (region) (
  time()
  - deploy_last_success_timestamp{project="reconcile", service_name=~"appliance-.*-host", appliance=~"$stage-.*", region=~"($region)"}
)

1 - avg by (region) (
  rate(node_cpu_seconds_total{mode="idle", service_name=~"appliance-.*-host", appliance=~"$stage-.*", region=~"($region)"}[5m])
)

max by (region) (
  1 - node_memory_MemAvailable_bytes{service_name=~"appliance-.*-host", appliance=~"$stage-.*", region=~"($region)"}
    / node_memory_MemTotal_bytes{service_name=~"appliance-.*-host", appliance=~"$stage-.*", region=~"($region)"}
)

max by (region) (
  1 - node_filesystem_avail_bytes{service_name=~"appliance-.*-host", appliance=~"$stage-.*", region=~"($region)", fstype!~"tmpfs|vfat|squashfs|overlay", mountpoint!~"/boot.*"}
    / node_filesystem_size_bytes{service_name=~"appliance-.*-host", appliance=~"$stage-.*", region=~"($region)", fstype!~"tmpfs|vfat|squashfs|overlay", mountpoint!~"/boot.*"}
)

sum by (host, handler, code) (
  rate(caddy_http_request_duration_seconds_count{service_name=~"appliance-.*-caddy", appliance=~"$stage-.*", region=~"($region)", code=~"5.."}[5m])
) * 60

histogram_quantile(0.95,
  sum by (host, le) (
    rate(caddy_http_request_duration_seconds_bucket{service_name=~"appliance-.*-caddy", appliance=~"$stage-.*", region=~"($region)"}[5m])
  )
)

histogram_quantile(0.95,
  sum by (host, method, le) (
    rate(caddy_http_response_duration_seconds_bucket{service_name=~"appliance-.*-caddy", appliance=~"$stage-.*", region=~"($region)"}[5m])
  )
)
